import sqlite3, os
con = sqlite3.connect(os.path.join(os.environ["TEMP"], "ov-audit-ro.db"))
print("=== per-hour: hy3 tokens vs search/find request counts (11-12 00:00 -> now) ===")
tok = {}
for d,h,p,m,tt,n in con.execute("select date_utc,hour_utc,provider,model_name,token_type,sum(token_count) from usage_token_hourly where date_utc>='2026-11-12' and model_name='auto/hy3' group by date_utc,hour_utc,token_type"):
    tok.setdefault((d,h),{}); tok[(d,h)][tt]=n
ret = {}
for d,h,op,st,rc in con.execute("select date_utc,hour_utc,operation,status,sum(request_count) from usage_retrieval_hourly where date_utc>='2026-11-12' group by date_utc,hour_utc,operation,status"):
    ret.setdefault((d,h),{}); ret[(d,h)][op+":"+st]=rc
for k in sorted(tok, reverse=True):
    t = tok[k]; r = ret.get(k, {})
    print(k, "in=%s out=%s" % (t.get("input",0), t.get("output",0)), "retrieval=", r)
print("=== totals since 11-12 ===")
for r in con.execute("select model_name,token_type,sum(token_count) from usage_token_hourly where date_utc>='2026-11-12' group by model_name,token_type"):
    print(r)
print("=== retrieval errors since 11-12 ===")
for r in con.execute("select date_utc,hour_utc,operation,status,request_count from usage_retrieval_hourly where date_utc>='2026-11-12' and status!='success'"):
    print(r)

